+    public static class FloatingPointComparisons extends MaskCompareNotBenchmark {
+        // "ULT", "ULE", "UGT", "UGE" are not supported for floating point types
+        @Param({"EQ", "NE", "LT", "LE", "GT", "GE"})
+        public String COMPARISON_OP;
